const r = $input.first().json;
if ((r.headers || {})['x-fill-secret'] !== 'cfabb602a3e7105a415b9e46c2e2c725f89107ec') throw new Error('bad secret');
const b = r.body || {}; const ITEMS = b.items;
if (!Array.isArray(ITEMS) || !ITEMS.length) throw new Error('no items');
const LID = { nl: 737, fr: 673, de: 666, it: 734, ko: 733, ms: 749, pt: 708, es: 1056, sv: 754, th: 753, vi: 774 };
const kids = [...new Set(ITEMS.map(x => x[1]))];
if (kids.length > 100) throw new Error('max 100 keys');
return [{ json: { mode: b.mode === 'all' ? 'all' : 'test', items: ITEMS, url: 'https://api.lokalise.com/api2/projects/479073796a6095e8c10e35.09051894/keys?limit=100&include_translations=1&disable_references=1&filter_translation_lang_ids=' + Object.values(LID).join(',') + '&filter_key_ids=' + kids.join(',') } }];

const PL = $('Payload').first().json; const b = $input.first().json;
if (!Array.isArray(b.keys)) throw new Error('no keys array: ' + JSON.stringify(b).slice(0,300));
const cur = {}; const tags = {};
for (const k of b.keys) { tags[k.key_id] = k.tags || []; for (const t of (k.translations || [])) cur[t.translation_id] = { v: typeof t.translation === 'object' ? JSON.stringify(t.translation) : (t.translation || ''), iso: t.language_iso, kid: k.key_id }; }
const out = []; const skipped = [];
for (const [tid, kid, iso, v, old] of PL.items) { const c = cur[tid];
  if (!c) { skipped.push({ tid, reason: 'not found' }); continue; }
  if (c.kid !== kid || c.iso !== iso) { skipped.push({ tid, reason: 'key/lang mismatch' }); continue; }
  if (c.v === v) { skipped.push({ tid, reason: 'already applied' }); continue; }
  const expected = (typeof old === 'string') ? old : '';
  if (c.v.trim() !== expected.trim()) { skipped.push({ tid, reason: 'changed since snapshot', now: c.v }); continue; }
  out.push({ json: { tid, iso, newv: v, url: 'https://api.lokalise.com/api2/projects/479073796a6095e8c10e35.09051894/translations/' + tid, body: { translation: v, is_reviewed: false, is_unverified: true } } });
  if (PL.mode === 'test') break; }
const noTag = Object.keys(tags).filter(k => !tags[k].includes('to_review'));
if (!out.length) throw new Error('NOTHING TO WRITE skipped=' + JSON.stringify(skipped).slice(0,1500) + ' noTag=' + noTag.join(','));
out[0].json.skipped = skipped; out[0].json.noTag = noTag;
return out;

const sent = $('Guard').all().map(i => i.json); const res = $input.all().map(i => i.json);
const ok = [], bad = [];
res.forEach((r, i) => { const s = sent[i]; const t = r.translation || {};
  if (t.translation === s.newv && t.is_reviewed === false && t.is_unverified === true) ok.push(s.tid);
  else bad.push({ tid: s.tid, got: JSON.stringify(r).slice(0, 300) }); });
const sk = sent[0].skipped || []; const odd = sk.filter(x => x.reason !== 'already applied');
return [{ json: { mode: $('Payload').first().json.mode, written: ok.length, okTids: ok, bad, odd, alreadyApplied: sk.length - odd.length, noTag: sent[0].noTag } }];
